WITH scored AS (SELECT *, MIN(credit_limit) OVER (PARTITION BY country ORDER BY credit_limit ASC, id ASC ROWS BETWEEN 3 PRECEDING AND CURRENT ROW) AS last4_min_credit_limit, COUNT(credit_limit) OVER (PARTITION BY country ORDER BY credit_limit ASC, id ASC ROWS BETWEEN 3 PRECEDING AND CURRENT ROW) AS last4_count_credit_limit, AVG(credit_limit) OVER (PARTITION BY country ORDER BY credit_limit ASC, id ASC ROWS BETWEEN 3 PRECEDING AND CURRENT ROW) AS last4_avg_credit_limit FROM customers), filtered AS (SELECT *, UPPER(email) AS email_upper, ROUND(last4_count_credit_limit, 2) AS last4_count_credit_limit_rounded, COALESCE(city, 'OTHER') AS resolved_city FROM scored WHERE signup_date >= DATE '2023-04-16'), with_windows AS (SELECT *, ROUND(credit_limit / SUM(credit_limit) OVER (PARTITION BY segment, city), 4) AS credit_limit_share, MAX(last4_min_credit_limit) OVER (PARTITION BY city, segment) AS city_max_last4_min_credit_limit, ROW_NUMBER() OVER w_hist AS seq_no FROM filtered WHERE segment = 'Consumer' WINDOW w_hist AS (ORDER BY last4_count_credit_limit DESC, id ASC)), with_windows_customers AS (SELECT id, email, country, city, is_active, last4_min_credit_limit, last4_avg_credit_limit, last4_count_credit_limit_rounded, resolved_city, credit_limit_share, city_max_last4_min_credit_limit, LEAD(age) OVER w_running AS next_age, LAG(age) OVER w_running AS prev_age, LEAD(last4_min_credit_limit) OVER w_running AS next_last4_min_credit_limit, LAG(last4_min_credit_limit) OVER w_running AS prev_last4_min_credit_limit, ROW_NUMBER() OVER w_running AS seq_no_2, AVG(city_max_last4_min_credit_limit) OVER (PARTITION BY country ORDER BY last4_avg_credit_limit ASC, id ASC ROWS BETWEEN 3 PRECEDING AND 1 PRECEDING) AS city_max_last4_min_credit_limit_avg_3_prior FROM with_windows WINDOW w_running AS (PARTITION BY city ORDER BY seq_no ASC, id ASC)), grouped AS (SELECT country, ROUND(SUM(city_max_last4_min_credit_limit) / NULLIF(COUNT(CASE WHEN country = 'SG' THEN 1 END), 0), 2) AS city_max_last4_min_credit_limit_per_sg, COUNT(DISTINCT id) AS distinct_ids, MAX(city_max_last4_min_credit_limit) AS max_city_max_last4_min_credit_limit, ROUND(SUM(next_age) / NULLIF(COUNT(CASE WHEN city = 'New York' THEN 1 END), 0), 2) AS next_age_per_new_york FROM with_windows_customers GROUP BY 1) SELECT country, city_max_last4_min_credit_limit_per_sg, distinct_ids, max_city_max_last4_min_credit_limit, next_age_per_new_york, CASE WHEN country RLIKE '^(US|JP)$' THEN 'OTHER_ZONE' ELSE 'GROUP_A' END AS country_zone FROM grouped
